package com.opensocket.aievent.core.issuetracking.application.recovery;
import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.opensocket.aievent.core.issuetracking.core.*;import com.opensocket.aievent.core.issuetracking.recovery.*;
@Service public class OrderedProjectionLaneService {private final ProjectionRecoveryRepository repo;private final ProjectionOrderingPolicy ordering=new ProjectionOrderingPolicy();private final ProjectionCoalescingPolicy coalescing=new ProjectionCoalescingPolicy();private final ProjectionBackpressurePolicy backpressure=new ProjectionBackpressurePolicy();private final ProjectionRecoveryEventLedger ledger;public OrderedProjectionLaneService(ProjectionRecoveryRepository repo,ProjectionRecoveryEventLedger ledger){this.repo=repo;this.ledger=ledger;}
 @Transactional public OrderedProjectionWork enqueue(String tenant,String aggregateKey,ProjectionLaneType laneType,String connection,String mapping,ProjectionOperationType operation,String aggregateId,String outboxId,String projectionId,String payloadHash,String coalesceKey,String dependsOnWorkId,int maxQueueDepth,int maxAttempts,String actor,String correlation){var lane=repo.findLaneByAggregate(req(tenant),req(aggregateKey),Objects.requireNonNull(laneType)).orElseGet(()->createLane(tenant,aggregateKey,laneType,connection,mapping,maxQueueDepth,actor,correlation));if(backpressure.reject(lane.queuedCount(),lane.maxQueueDepth(),operation))throw new IllegalStateException("PROJECTION_LANE_SATURATED");boolean depAck=dependsOnWorkId==null||dependsOnWorkId.isBlank()||repo.findWork(tenant,dependsOnWorkId).map(v->v.status()==ProjectionWorkStatus.ACKNOWLEDGED).orElse(false);long sequence=lane.nextSequence();OffsetDateTime now=now();String workId="pw-"+UUID.randomUUID();int supersededCount=0;if(coalescing.coalescible(operation)&&coalesceKey!=null&&!coalesceKey.isBlank()){for(var old:repo.findCoalescible(tenant,lane.laneId(),coalesceKey,lane.activeGeneration(),100)){if(!old.terminal()){var superseded=copy(old,ProjectionWorkStatus.SUPERSEDED,workId,old.version()+1,now,"COALESCED_BY_NEWER_UPDATE",null);if(repo.saveWorkExpectedVersion(superseded,old.version()))supersededCount++;ledger.append(tenant,"PROJECTION_WORK",old.workId(),ProjectionRecoveryEventType.WORK_SUPERSEDED,actor,"COALESCED",json("supersededBy",workId),correlation);}}}var status=ordering.initialStatus(operation,dependsOnWorkId,depAck);var work=new OrderedProjectionWork(tenant,workId,lane.laneId(),sequence,lane.activeGeneration(),operation,status,req(aggregateId),blank(outboxId),blank(projectionId),req(payloadHash),blank(coalesceKey),blank(dependsOnWorkId),"",marker(lane.laneId(),sequence,lane.activeGeneration()),0,Math.max(1,maxAttempts),"","",null,now,"","",1,now,now,correlation);repo.saveWork(work);var next=new OrderedProjectionLane(lane.tenantId(),lane.laneId(),lane.aggregateKey(),lane.laneType(),lane.connectionId(),lane.projectMappingId(),lane.status(),sequence+1,lane.activeGeneration(),lane.maxQueueDepth(),Math.max(0,lane.queuedCount()-supersededCount)+1,lane.inFlightCount(),lane.version()+1,lane.createdAt(),now,correlation);if(!repo.saveLaneExpectedVersion(next,lane.version()))throw new IllegalStateException("PROJECTION_LANE_VERSION_CONFLICT");ledger.append(tenant,"PROJECTION_LANE",lane.laneId(),status==ProjectionWorkStatus.BLOCKED?ProjectionRecoveryEventType.WORK_BLOCKED:ProjectionRecoveryEventType.WORK_ENQUEUED,actor,operation.name(),json("workId",workId),correlation);return work;}
 @Transactional public OrderedProjectionLane nextGeneration(String tenant,String laneId,long expectedVersion,String actor,String reason,String correlation){var lane=getLane(tenant,laneId);if(lane.version()!=expectedVersion)throw new IllegalStateException("PROJECTION_LANE_VERSION_CONFLICT");OffsetDateTime now=now();int supersededCount=0;for(var work:repo.listWork(tenant,laneId,null,1000)){if(work.generation()==lane.activeGeneration()&&!work.terminal()){var superseded=copy(work,ProjectionWorkStatus.SUPERSEDED,"generation:"+(lane.activeGeneration()+1),work.version()+1,now,"SUPERSEDED_BY_NEW_GENERATION",null);if(repo.saveWorkExpectedVersion(superseded,work.version())){supersededCount++;ledger.append(tenant,"PROJECTION_WORK",work.workId(),ProjectionRecoveryEventType.WORK_SUPERSEDED,actor,reason,json("generation",String.valueOf(lane.activeGeneration()+1)),correlation);}}}var next=new OrderedProjectionLane(lane.tenantId(),lane.laneId(),lane.aggregateKey(),lane.laneType(),lane.connectionId(),lane.projectMappingId(),ProjectionLaneStatus.RECOVERING,lane.nextSequence(),lane.activeGeneration()+1,lane.maxQueueDepth(),Math.max(0,lane.queuedCount()-supersededCount),0,lane.version()+1,lane.createdAt(),now,correlation);if(!repo.saveLaneExpectedVersion(next,lane.version()))throw new IllegalStateException("PROJECTION_LANE_VERSION_CONFLICT");return next;}
 public List<OrderedProjectionLane> list(String tenant,ProjectionLaneStatus status,int limit){return repo.listLanes(req(tenant),status,lim(limit));}public List<OrderedProjectionWork> work(String tenant,String laneId,ProjectionWorkStatus status,int limit){return repo.listWork(req(tenant),blank(laneId),status,lim(limit));}public OrderedProjectionLane getLane(String tenant,String id){return repo.findLane(req(tenant),req(id)).orElseThrow(()->new IllegalArgumentException("Projection lane not found."));}
 private OrderedProjectionLane createLane(String tenant,String key,ProjectionLaneType type,String connection,String mapping,int depth,String actor,String corr){OffsetDateTime now=now();var lane=new OrderedProjectionLane(req(tenant),"lane-"+UUID.randomUUID(),req(key),type,req(connection),blank(mapping),ProjectionLaneStatus.ACTIVE,1,1,Math.max(10,depth),0,0,1,now,now,corr);repo.saveLane(lane);ledger.append(tenant,"PROJECTION_LANE",lane.laneId(),ProjectionRecoveryEventType.LANE_CREATED,actor,"CREATED",json("aggregateKey",key),corr);return lane;}private OrderedProjectionWork copy(OrderedProjectionWork v,ProjectionWorkStatus s,String superseded,long version,OffsetDateTime now,String code,OffsetDateTime next){return new OrderedProjectionWork(v.tenantId(),v.workId(),v.laneId(),v.laneSequence(),v.generation(),v.operationType(),s,v.aggregateId(),v.outboxId(),v.projectionId(),v.payloadHash(),v.coalesceKey(),v.dependsOnWorkId(),superseded,v.externalIdempotencyMarker(),v.attemptCount(),v.maxAttempts(),v.claimOwner(),v.claimTokenHash(),v.claimUntil(),next,code,v.lastErrorMessage(),version,v.createdAt(),now,v.correlationId());}private String marker(String lane,long seq,long gen){return "opendispatch:"+lane+":"+gen+":"+seq;}private String json(String k,String v){String safe=v==null?"":v.replace("\\","\\\\").replace("\"","\'");return "{\""+k+"\":\""+safe+"\"}";}private String req(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value missing.");return v.trim();}private String blank(String v){return v==null?"":v.trim();}private int lim(int n){return Math.max(1,Math.min(n,1000));}private OffsetDateTime now(){return OffsetDateTime.now(ZoneOffset.UTC);} }
